"""Optional, bounded coworker exchanges; reconnect to the pending major decision."""
def conversation(s,kind):
 w=s['staff'];name={'maya':'Maya','jordan':'Jordan','sam':'Sam'}[w]
 if kind=='coffee':
  opening={'maya':'Warehouse coffee has survived more migrations than this system. I am not sure that is a recommendation.','jordan':'I thought the warehouse coffee was strong. Then Rosa told me that was the mild batch.','sam':'I asked where the good coffee was. Apparently that was my first rookie mistake.'}[w]
  return [dict(line=opening,choices=[('I will stick to water. How are you settling in?',1),('Coffee is the least of our problems. Back to work.',-1)]),dict(line='Busy, but clearer priorities help. Being able to ask before a small uncertainty becomes a big problem matters more than the coffee.',choices=[('Keep raising those questions. We can be clear without pretending everything is obvious.',1),('Just try not to bring me every little thing.',-1)]),dict(line='Understood. I will bring the relevant uncertainties and an explanation of their impact. Now, about the migration evidence…',choices=[])]
 opening={'maya':'The printer has jammed again. At least it is consistent about its acceptance criteria.','jordan':'The training handouts are ready. The printer has chosen not to participate.','sam':'I fixed the printer once and now everyone thinks I own it. I may have made an unfortunate career decision.'}[w]
 return [dict(line=opening,choices=[('We will find another way to share them. How is the team doing?',1),('We do not have time for printer stories.',-1)]),dict(line='People want to be ready. They need the materials and time to practice, not another promise that the system is easy.',choices=[('Fair. Let us protect the rehearsal time and sort out access to the materials.',1),('They will figure it out once it is live.',-1)]),dict(line='We can review the readiness plan now. Let us make the support explicit.',choices=[])]
